# Lab files update for the Skillable VM.
# Generated by scripts/publish-lab-vm-update.mjs from scripts/lab-vm-update.template.ps1. Edit the template, not the generated copy.
# Runs with "irm <url> | iex", so it must never call exit. Works on Windows PowerShell 5.1 and PowerShell 7.
# Output is ASCII only: Windows PowerShell 5.1 garbles emoji in console output.

& {
    $ErrorActionPreference = 'Stop'

    $build = @'
__BUILD_JSON__
'@ | ConvertFrom-Json

    $payload = @'
__PAYLOAD_BASE64__
'@

    # Override for testing the script away from the VM.
    $labRoot = if ($env:LAB_FILES_DIR) { $env:LAB_FILES_DIR } else { $build.labRoot }
    $versionPath = Join-Path $labRoot 'lab-files.json'
    $sep = [string][IO.Path]::DirectorySeparatorChar

    $results = New-Object System.Collections.Generic.List[object]

    function Add-Result([string]$Group, [string]$Target, [string]$Status, [string]$Details) {
        $results.Add([pscustomobject]@{ Group = $Group; Status = $Status; Target = $Target; Details = $Details })
    }

    # Runs $Action in a child scope: it sees this script's variables, but not ones named like these parameters.
    function Invoke-Update([string]$Group, [string]$Target, [scriptblock]$Action) {
        try {
            Add-Result $Group $Target 'OK' ([string](& $Action))
        } catch {
            Add-Result $Group $Target 'FAILED' $_.Exception.Message
        }
    }

    function Get-LocalPath([string]$Root, [string]$RelativePath) {
        [IO.Path]::Combine($Root, $RelativePath.Replace('/', $sep))
    }

    # Replaces the destination folder; the files named in $Keep (paths relative to it) survive the update.
    function Copy-Folder([string]$Source, [string]$Destination, [string[]]$Keep) {
        if (-not (Test-Path -LiteralPath $Source -PathType Container)) { throw "Missing from the package: $Source" }
        $kept = @{}
        foreach ($name in $Keep) {
            $path = Get-LocalPath $Destination $name
            if (Test-Path -LiteralPath $path -PathType Leaf) { $kept[$name] = [IO.File]::ReadAllBytes($path) }
        }
        if (Test-Path -LiteralPath $Destination) { Remove-Item -LiteralPath $Destination -Recurse -Force }
        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $Destination) | Out-Null
        Copy-Item -LiteralPath $Source -Destination $Destination -Recurse -Force
        foreach ($name in $kept.Keys) {
            $path = Get-LocalPath $Destination $name
            New-Item -ItemType Directory -Force -Path (Split-Path -Parent $path) | Out-Null
            [IO.File]::WriteAllBytes($path, $kept[$name])
        }
        $count = @(Get-ChildItem -LiteralPath $Destination -Recurse -File -Force).Count
        $files = if ($count -eq 1) { '1 file' } else { "$count files" }
        if ($kept.Count) { "$files ($($kept.Count) kept)" } else { $files }
    }

    function Copy-File([string]$Source, [string]$Destination) {
        if (-not (Test-Path -LiteralPath $Source -PathType Leaf)) { throw "Missing from the package: $Source" }
        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $Destination) | Out-Null
        Copy-Item -LiteralPath $Source -Destination $Destination -Force
        'Copied'
    }

    Write-Host ''
    Write-Host "$($build.name) lab files update"
    $suffix = if ($build.dirty) { ' with local changes' } else { '' }
    Write-Host "Build $($build.shortCommit)$suffix, built $($build.builtAt)"
    Write-Host ''

    $work = Join-Path ([IO.Path]::GetTempPath()) ('lab-vm-update-' + [guid]::NewGuid().ToString('N'))
    $staging = Join-Path $work 'package'
    try {
        $unpackError = $null
        try {
            New-Item -ItemType Directory -Force -Path $work | Out-Null
            $zipPath = Join-Path $work 'lab-files.zip'
            [IO.File]::WriteAllBytes($zipPath, [Convert]::FromBase64String($payload))
            $hash = (Get-FileHash -LiteralPath $zipPath -Algorithm SHA256).Hash
            if ($hash -ne $build.sha256) { throw 'The download is corrupted (checksum mismatch). Run the command again.' }
            Add-Type -AssemblyName System.IO.Compression.FileSystem
            [IO.Compression.ZipFile]::ExtractToDirectory($zipPath, $staging)
        } catch {
            $unpackError = "Package not unpacked: $($_.Exception.Message)"
        }

        if ($unpackError) {
            foreach ($entry in $build.groups) { Add-Result $entry.name (Get-LocalPath $labRoot $entry.target) 'FAILED' $unpackError }
        } else {
            foreach ($entry in $build.groups) {
                $entrySource = Get-LocalPath (Join-Path $staging 'files') $entry.target
                $entryTarget = Get-LocalPath $labRoot $entry.target
                Invoke-Update $entry.name $entryTarget {
                    if ($entry.kind -eq 'file') {
                        Copy-File $entrySource $entryTarget
                    } else {
                        Copy-Folder $entrySource $entryTarget @($entry.keep | Where-Object { $_ })
                    }
                }
            }

            # --- Lab-specific steps (start) ---------------------------------------------------------------
            # Add steps that the file groups can't express here, each in its own Invoke-Update so its result
            # shows in the table. $labRoot is the lab folder, already updated; $staging holds the unpacked package.
            # Example: Invoke-Update 'My step' $stepTarget { <do the work>; 'Short result' }

            # Runs a command and returns its stdout; throws with its stderr when it fails. Output goes to temp files,
            # not PowerShell pipes: node can crash on exit (0xC0000409) when its stdout is a pipe on Windows, and
            # npm notices on stderr must not end up in the parsed output.
            function Invoke-Npm([string]$FilePath, [string[]]$Arguments) {
                $outFile = [IO.Path]::GetTempFileName()
                $errFile = [IO.Path]::GetTempFileName()
                $previousNotifier = $env:NPM_CONFIG_UPDATE_NOTIFIER
                $env:NPM_CONFIG_UPDATE_NOTIFIER = 'false'
                try {
                    $quoted = @($Arguments | ForEach-Object { if ($_ -match '\s') { '"' + $_ + '"' } else { $_ } })
                    $process = Start-Process -FilePath $FilePath -ArgumentList $quoted -NoNewWindow -PassThru `
                        -RedirectStandardOutput $outFile -RedirectStandardError $errFile
                    # Reading Handle first makes ExitCode reliable in Windows PowerShell 5.1.
                    $null = $process.Handle
                    $process.WaitForExit()
                    $code = $process.ExitCode
                    $stdout = [IO.File]::ReadAllText($outFile).Trim()
                    $stderr = [IO.File]::ReadAllText($errFile).Trim()
                } finally {
                    $env:NPM_CONFIG_UPDATE_NOTIFIER = $previousNotifier
                    Remove-Item -LiteralPath $outFile, $errFile -Force -ErrorAction SilentlyContinue
                }
                if ($code -ne 0) {
                    $details = if ($stderr) { $stderr } else { $stdout }
                    throw "$(Split-Path -Leaf $FilePath) $($Arguments -join ' ') failed (exit code $code): $details"
                }
                $stdout
            }

            # The last non-empty line of a command's output, where npm prints versions.
            function Get-LastLine([string]$Text) {
                $lines = @($Text -split "`r?`n" | Where-Object { $_.Trim() })
                if ($lines.Count) { $lines[-1].Trim() } else { '' }
            }

            $isWindowsOs = $env:OS -eq 'Windows_NT'
            $npmCommand = if ($isWindowsOs) { 'npm.cmd' } else { 'npm' }
            $npxCommand = if ($isWindowsOs) { 'npx.cmd' } else { 'npx' }
            $npmPath = (Get-Command $npmCommand -ErrorAction SilentlyContinue | Select-Object -First 1).Source
            $npxPath = (Get-Command $npxCommand -ErrorAction SilentlyContinue | Select-Object -First 1).Source
            $nodePath = (Get-Command 'node' -ErrorAction SilentlyContinue | Select-Object -First 1).Source

            Invoke-Update 'npm (latest)' $(if ($npmPath) { $npmPath } else { 'npm' }) {
                if (-not $npmPath) { throw 'npm is not on PATH. Install Node.js first.' }
                $current = Get-LastLine (Invoke-Npm $npmPath @('--version'))
                $latest = Get-LastLine (Invoke-Npm $npmPath @('view', 'npm@latest', 'version'))
                if ($latest -notmatch '^\d+\.\d+\.\d+') { throw "Unexpected latest npm version: $latest" }
                if ($current -eq $latest) {
                    "Already $current"
                } elseif ($env:LAB_FILES_DIR) {
                    "Test run: would update $current -> $latest"
                } else {
                    # Install over the npm that PATH resolves (on Windows, the global prefix is the folder holding
                    # npm.cmd), not into %APPDATA%\npm, where the old npm in the Node.js folder would still win.
                    # Run npm-cli.js with node, because npm.cmd can break while it overwrites itself.
                    $npmDir = Split-Path -Parent $npmPath
                    $npmCli = [IO.Path]::Combine($npmDir, 'node_modules', 'npm', 'bin', 'npm-cli.js')
                    $installArgs = @('install', '-g', "npm@$latest", '--engine-strict', '--no-fund', '--no-audit')
                    try {
                        if ($isWindowsOs -and $nodePath -and (Test-Path -LiteralPath $npmCli)) {
                            Invoke-Npm $nodePath (@($npmCli) + $installArgs + @('--prefix', $npmDir)) | Out-Null
                        } else {
                            Invoke-Npm $npmPath $installArgs | Out-Null
                        }
                    } catch {
                        $message = $_.Exception.Message
                        if ($message -match 'EPERM|EACCES') { throw 'No permission to update the global npm. Open PowerShell as administrator and run the command again.' }
                        if ($message -match 'EBADENGINE') { throw "npm $latest doesn't support the installed Node.js version. Update Node.js first." }
                        throw
                    }
                    $updated = Get-LastLine (Invoke-Npm $npmPath @('--version'))
                    if ($updated -ne $latest) { throw "npm $latest was installed, but $npmPath still runs npm $updated. Check PATH." }
                    "$current -> $updated"
                }
            }

            $templateDir = Get-LocalPath $labRoot 'template/field-services-app'
            Invoke-Update 'Rayfin CLI cache' 'npm cache' {
                $cliVersion = $null
                $lockPath = Join-Path $templateDir 'package-lock.json'
                # A regex, because ConvertFrom-Json in Windows PowerShell 5.1 can choke on large lockfiles.
                if (Test-Path -LiteralPath $lockPath) {
                    $lockText = [IO.File]::ReadAllText($lockPath)
                    $found = [regex]::Match($lockText, '"node_modules/@microsoft/rayfin-cli"\s*:\s*\{[^{}]*?"version"\s*:\s*"([^"]+)"')
                    if ($found.Success) { $cliVersion = $found.Groups[1].Value }
                }
                if (-not $cliVersion) {
                    $manifest = Get-Content -Raw -LiteralPath (Join-Path $templateDir 'package.json') | ConvertFrom-Json
                    $cliVersion = $manifest.devDependencies.'@microsoft/rayfin-cli'
                }
                if (-not $cliVersion) { throw 'No @microsoft/rayfin-cli version found in the template.' }
                if (-not $npxPath) { throw 'npx is not on PATH. Install Node.js first.' }
                $printed = Get-LastLine (Invoke-Npm $npxPath @('-y', "@microsoft/rayfin-cli@$cliVersion", '--version'))
                "@microsoft/rayfin-cli@$cliVersion cached (prints $printed)"
            }
            # --- Lab-specific steps (end) -----------------------------------------------------------------
        }

        if ($unpackError) {
            Add-Result 'Version stamp' $versionPath 'FAILED' 'Skipped: package not unpacked.'
        } else {
            Invoke-Update 'Version stamp' $versionPath {
                New-Item -ItemType Directory -Force -Path $labRoot | Out-Null
                Copy-Item -LiteralPath (Join-Path $staging 'manifest.json') -Destination $versionPath -Force
                $build.shortCommit
            }
        }
    } finally {
        if (Test-Path -LiteralPath $work) { Remove-Item -LiteralPath $work -Recurse -Force -ErrorAction SilentlyContinue }
    }

    $results | Format-Table -AutoSize -Wrap | Out-String -Width 4096 | Write-Host

    $failed = @($results | Where-Object { $_.Status -ne 'OK' }).Count
    if ($failed -eq 0) {
        Write-Host 'All updates succeeded.' -ForegroundColor Green
    } else {
        Write-Host "$failed update(s) failed. Fix the cause shown above, then run the same command again." -ForegroundColor Red
    }
    Write-Host ''
}
